
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ev93_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ev93", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.281219780704182e+00, -4.200436283701676e+00, -4.087510001906243e+00, -3.931661994369210e+00, -3.720571672036813e+00, -3.442449499621756e+00, -3.090822886912095e+00, -2.673214994318703e+00, -2.220815747429426e+00, -1.769074623563216e+00, -1.230489216616595e+00, -7.202901497136508e-01, -5.989776582156809e-01, -5.031039296603338e-01, -3.908479537944287e-01, -2.872336815849711e-01, -1.718913698761455e-01, -5.134590639413498e-02, -9.367979583374608e-03, -1.039883503532051e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


